changeSet.sql:
ALTER TABLE nexus.request_ledger ENABLE ROW LEVEL SECURITY;
ALTER TABLE nexus.request_ledger FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON nexus.request_ledger
    USING      (tenant_id = current_setting('nexus.tenant', true))
    WITH CHECK (tenant_id = current_setting('nexus.tenant', true));

changeSet.rollback:
DROP POLICY IF EXISTS tenant_isolation ON nexus.request_ledger;
ALTER TABLE nexus.request_ledger NO FORCE ROW LEVEL SECURITY;
ALTER TABLE nexus.request_ledger DISABLE ROW LEVEL SECURITY;
